const body = $input.first().json.body;
const target = body.target || '';
const domain = body.domain || 'general';
const depth = body.depth || 'standard';

if (!target) {
  throw new Error('Missing required field: target');
}

return [{ json: { target, domain, depth, timestamp: new Date().toISOString() } }];

const { target, domain, depth } = $json;
return [{
  json: {
    task: `Perform a code review of: ${target}. Domain: ${domain}. Focus on security, correctness, maintainability, performance, testing.`,
    context: { agent_id: 'code-reviewer', code: target, language: domain, review_level: depth }
  }
}];

const { target, domain } = $('Validate Input').first().json;
return [{
  json: {
    task: `Improve the prompt used for auditing. Create a structured audit checklist for domain: ${domain}.`,
    context: { agent_id: 'prompter', prompt: `Audit checklist for ${domain} domain. Target: ${target.substring(0, 200)}`, level: 2, domain }
  }
}];

const codeReview = $('Phase 1: Code Review').first().json;
const promptAudit = $('Phase 1: Prompt Quality').first().json;
const crResult = codeReview.result || codeReview;
const paResult = promptAudit.result || promptAudit;

return [{
  json: {
    target: $('Validate Input').first().json.target,
    domain: $('Validate Input').first().json.domain,
    depth: $('Validate Input').first().json.depth,
    code_review: { findings: crResult.findings || [], summary: crResult.summary || '', severity_counts: crResult.severity_counts || {} },
    prompt_quality: { level_applied: paResult.level_applied || 0, changes: paResult.changes_made || [], improved_prompt: paResult.improved_prompt || '' }
  }
}];

const target = $('Validate Input').first().json.target;
const findings = JSON.stringify($('Phase 2: Synthesis').first().json.code_review.findings).substring(0, 500);
return [{
  json: {
    task: `Second-order audit: Review findings. Are they grounded? Priorities correct? Early warnings included?`,
    context: { agent_id: 'critic-premortem', plan: `Code review of ${target.substring(0, 200)}. Findings: ${findings}`, level: 2 }
  }
}];

const synthesis = $('Phase 2: Synthesis').first().json;
let secondOrder = null;
try { const so = $('Phase 3: Second-Order').first().json; secondOrder = so.result || so; } catch (e) {}

const findings = synthesis.code_review.findings || [];
const blockers = findings.filter(f => f.severity === 'blocker').length;
const suggestions = findings.filter(f => f.severity === 'suggestion').length;
let score = Math.max(0, Math.min(100, 100 - blockers * 20 - suggestions * 5));
let verdict = score >= 80 ? 'READY' : score >= 60 ? 'NEEDS_WORK' : 'NOT_READY';

return [{ json: { status: 'completed', target: synthesis.target, domain: synthesis.domain, readiness_score: score, verdict, code_review: synthesis.code_review, prompt_quality: synthesis.prompt_quality, second_order_audit: secondOrder ? { summary: secondOrder.summary || '', checklist: secondOrder.checklist || [] } : null, timestamp: new Date().toISOString() } }];
